import osimport sqlite3import pandas as pdfrom src.analytics.ratios import (    high_leverage_flag,    return_on_capital_employed,    return_on_equity,)DB_PATH = "data/nifty100.db"COMPANIES_FILE = "data/raw/core/companies.xlsx"LOG_FILE = "output/ratio_edge_cases.log"def load_source_data():    """Load ROCE and ROE values from companies.xlsx."""    companies = pd.read_excel(COMPANIES_FILE, header=1)    companies.columns = [str(column).strip() for column in companies.columns]    companies["id"] = companies["id"].astype(str).str.strip()    return companiesdef get_financials_companies(connection):    """Get the distinct companies classified as Financials."""    query = """        SELECT DISTINCT            c.id,            c.company_name,            s.broad_sector        FROM companies AS c        JOIN sectors AS s            ON c.id = s.company_id        WHERE LOWER(TRIM(s.broad_sector)) = 'financials'        ORDER BY c.id    """    return connection.execute(query).fetchall()def get_financial_data(connection):    """Get annual financial data needed for ROCE and ROE."""    query = """        SELECT            p.company_id,            c.company_name,            p.year,            p.period,            p.operating_profit,            p.other_income,            p.net_profit,            b.equity_capital,            b.reserves,            b.borrowings        FROM profitandloss AS p        JOIN companies AS c            ON c.id = p.company_id        LEFT JOIN balancesheet AS b            ON b.company_id = p.company_id            AND b.period = p.period        WHERE p.period LIKE 'Mar %'        ORDER BY            p.company_id,            p.year    """    return connection.execute(query).fetchall()def calculate_ratios(row):    """Calculate ROCE and ROE using the existing ratio formulas."""    (        company_id,        company_name,        year,        period,        operating_profit,        other_income,        net_profit,        equity_capital,        reserves,        borrowings,    ) = row    calculated_roce = return_on_capital_employed(        operating_profit,        other_income,        equity_capital,        reserves,        borrowings,    )    calculated_roe = return_on_equity(        net_profit,        equity_capital,        reserves,    )    return {        "company_id": company_id,        "company_name": company_name,        "year": year,        "period": period,        "calculated_roce": calculated_roce,        "calculated_roe": calculated_roe,    }def get_source_values(source_data, company_id):    """Get the pre-computed ROCE and ROE for one company."""    matches = source_data[source_data["id"] == str(company_id).strip()]    if matches.empty:        return None, None    row = matches.iloc[0]    source_roce = row["roce_percentage"]    source_roe = row["roe_percentage"]    if pd.isna(source_roce):        source_roce = None    if pd.isna(source_roe):        source_roe = None    return source_roce, source_roedef calculate_difference(calculated, source):    """Return the absolute difference between two ratio values."""    if calculated is None or source is None:        return None    return abs(calculated - source)def classify_anomaly(    company_id,    company_name,    calculated_roce,    source_roce,    calculated_roe,    source_roe,):    """    Give an initial category to an anomaly.    These categories are deliberately conservative.    A source value that is clearly strange is treated as    a data source issue. Other differences are left for    manual review.    """    if company_id == "TCS" and source_roe is not None and source_roe == 0.52:        return "DATA_SOURCE_ISSUE"    if calculated_roce is None or source_roce is None:        return "DATA_SOURCE_ISSUE"    if calculated_roe is None or source_roe is None:        return "DATA_SOURCE_ISSUE"    return "REVIEW_REQUIRED"def review_financials(connection):    """Check the Financials D/E carve-out."""    rows = get_financials_companies(connection)    print()    print("Financials company check")    print()    print("Distinct Financials companies:", len(rows))    for company_id, company_name, broad_sector in rows:        ratio_rows = connection.execute(            """            SELECT                debt_to_equity            FROM financial_ratios            WHERE company_id = ?            ORDER BY year            """,            (company_id,),        ).fetchall()        for ratio_row in ratio_rows:            debt_equity = ratio_row[0]            warning = high_leverage_flag(                debt_equity,                broad_sector,            )            print(f"{company_id}: D/E={debt_equity} high_leverage_warning={warning}")    return rowsdef write_log(    financials,    audit_rows,):    """Write the Day 13 edge-case log."""    os.makedirs(        "output",        exist_ok=True,    )    with open(        LOG_FILE,        "w",        encoding="utf-8",    ) as log:        log.write("Day 13 - Bank ROCE Carve-Out and Edge Case Log\n")        log.write("\n")        log.write("Financials sector check\n")        log.write("\n")        log.write(f"Distinct Financials companies found: {len(financials)}\n")        log.write("Task reference count: 19\n")        log.write(            f"The database currently contains {len(financials)} distinct "            "companies classified as Financials.\n"        )        log.write(            "The D/E warning is suppressed for all companies "            "classified as Financials.\n"        )        log.write("\n")        log.write("Financials companies\n")        log.write("\n")        log.writelines(            f"{company_id} | {company_name.strip()} | {broad_sector}\n"            for company_id, company_name, broad_sector in financials        )        log.write("\n")        log.write("Ratio edge cases\n")        log.write("\n")        anomaly_count = 0        for row in audit_rows:            roce_difference = row["roce_difference"]            roe_difference = row["roe_difference"]            roce_anomaly = roce_difference is not None and roce_difference > 5            roe_anomaly = roe_difference is not None and roe_difference > 5            if not roce_anomaly and not roe_anomaly:                continue            anomaly_count += 1            log.write("Company: {}\n".format(row["company_name"].strip()))            log.write("Company ID: {}\n".format(row["company_id"]))            log.write("Year: {}\n".format(row["year"]))            log.write("Calculated ROCE: {}\n".format(row["calculated_roce"]))            log.write("Source ROCE: {}\n".format(row["source_roce"]))            log.write("ROCE difference: {}\n".format(row["roce_difference"]))            log.write("Calculated ROE: {}\n".format(row["calculated_roe"]))            log.write("Source ROE: {}\n".format(row["source_roe"]))            log.write("ROE difference: {}\n".format(row["roe_difference"]))            log.write("Category: {}\n".format(row["category"]))            log.write(                "Note: The ratio engine value is used for "                "analytics. The source value is retained only "                "for display and audit comparison.\n"            )            log.write("\n")        log.write(f"Total ratio edge cases: {anomaly_count}\n")        log.write("\n")        log.write("Category definitions\n")        log.write("\n")        log.write(            "DATA_SOURCE_ISSUE: The source value appears "            "incorrect, missing, or inconsistent with the "            "underlying financial data.\n"        )        log.write(            "VERSION_DIFFERENCE: The calculated and source "            "values may come from different data versions "            "or reporting periods.\n"        )        log.write(            "FORMULA_DISCREPANCY: The difference appears "            "to come from different calculation definitions.\n"        )        log.write("\n")        log.write("ANALYTICS RULE\n")        log.write("\n")        log.write(            "The ratio engine value is used for ROE and ROCE "            "analytics. The companies.xlsx value is used "            "only as a source/display reference.\n"        )def main():    """Run the main workflow."""    print("Day 13 - Ratio edge case review")    print()    source_data = load_source_data()    connection = sqlite3.connect(DB_PATH)    try:        financials = review_financials(connection)        financial_rows = get_financial_data(connection)        audit_rows = []        for row in financial_rows:            calculated = calculate_ratios(row)            source_roce, source_roe = get_source_values(                source_data,                calculated["company_id"],            )            calculated["source_roce"] = source_roce            calculated["source_roe"] = source_roe            calculated["roce_difference"] = calculate_difference(                calculated["calculated_roce"],                source_roce,            )            calculated["roe_difference"] = calculate_difference(                calculated["calculated_roe"],                source_roe,            )            calculated["category"] = classify_anomaly(                calculated["company_id"],                calculated["company_name"],                calculated["calculated_roce"],                source_roce,                calculated["calculated_roe"],                source_roe,            )            audit_rows.append(calculated)        roce_anomalies = [            row            for row in audit_rows            if (row["roce_difference"] is not None and row["roce_difference"] > 5)        ]        roe_anomalies = [            row            for row in audit_rows            if (row["roe_difference"] is not None and row["roe_difference"] > 5)        ]        print()        print(            "ROCE anomalies greater than 5:",            len(roce_anomalies),        )        print(            "ROE anomalies greater than 5:",            len(roe_anomalies),        )        write_log(            financials,            audit_rows,        )        print()        print(            "Log created:",            LOG_FILE,        )    finally:        connection.close()if __name__ == "__main__":    main()